css:
.google-home {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding-top: 100px;
  font-family: Arial, sans-serif;
}

/* LOGO STYLIZACJA */
.google-logo {
  font-size: 80px;
  font-weight: bold;
  margin-bottom: 20px;
  letter-spacing: -2px;
}
.g {
  color: #4285f4;
}
.o1 {
  color: #ea4335;
}
.o2 {
  color: #fbbc05;
}
.l {
  color: #34a853;
}
.e {
  color: #ea4335;
}

/* PASEK WYSZUKIWANIA */
.search-box {
  display: flex;
  align-items: center;
  width: 500px;
  border: 1px solid #dfe1e5;
  border-radius: 24px;
  padding: 10px 20px;
  margin-bottom: 25px;
}
.search-box:hover {
  box-shadow: 0 1px 6px rgba(32, 33, 36, 0.28);
  border-color: transparent;
}
.search-icon {
  width: 20px;
  height: 20px;
  fill: #9aa0a6;
  margin-right: 15px;
}
.search-input {
  border: none;
  outline: none;
  width: 100%;
  font-size: 16px;
}

/* PRZYCISKI */
.buttons {
  display: flex;
  gap: 10px;
}
.btn {
  background: #f8f9fa;
  border: 1px solid #f8f9fa;
  border-radius: 4px;
  color: #3c4043;
  padding: 10px 16px;
  font-size: 14px;
  cursor: pointer;
}
.btn:hover {
  border: 1px solid #dadce0;
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.1);
  color: #202124;
}
